const size_t kInternalKeySize = 7;
if (internal_key.size() < kInternalKeySize) {
    return false;
}
uint64_t decoded_sequence = 0;
uint8_t decoded_type = 0;
std::memcpy(&decoded_sequence, internal_key.data() + internal_key.size() - 8, 7);
decoded_type = internal_key.data()[internal_key.size() - 1];
*sequence = std::ntohll(decoded_sequence);
*type = decoded_type;
*user_key = Slice(internal_key.data(), internal_key.size() - kInternalKeySize);
return true;

